BEGIN;
CREATE TABLE public.academic_workflow_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,school_id uuid NOT NULL,resource_type text NOT NULL CHECK(resource_type IN ('assessment','grade','attendance_session','report_card')),resource_id uuid NOT NULL,actor_user_id uuid NOT NULL REFERENCES public.users(id),from_state text,to_state text NOT NULL,action text NOT NULL CHECK(action IN ('create','edit','submit','approve','reject','publish','request_revision','supersede','correct','revoke_publication')),reason text,request_id uuid NOT NULL,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),FOREIGN KEY(tenant_id,school_id) REFERENCES public.schools(tenant_id,id),UNIQUE(tenant_id,school_id,request_id));
CREATE INDEX academic_events_resource_idx ON public.academic_workflow_events(tenant_id,school_id,resource_type,resource_id,occurred_at DESC);
CREATE TABLE public.academic_revision_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,school_id uuid NOT NULL,resource_type text NOT NULL CHECK(resource_type IN ('grade','attendance_session','report_card')),resource_id uuid NOT NULL,requested_by uuid NOT NULL REFERENCES public.users(id),reason text NOT NULL CHECK(length(trim(reason))>=10),state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','approved','rejected','applied','cancelled')),reviewed_by uuid REFERENCES public.users(id),reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),FOREIGN KEY(tenant_id,school_id) REFERENCES public.schools(tenant_id,id),CHECK(reviewed_by IS NULL OR reviewed_by<>requested_by),CHECK((state IN ('approved','rejected','applied'))=(reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)));
CREATE INDEX academic_revision_pending_idx ON public.academic_revision_requests(tenant_id,school_id,state,created_at);
CREATE TABLE public.academic_publication_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,school_id uuid NOT NULL,resource_type text NOT NULL CHECK(resource_type IN ('grade','attendance_session','report_card')),resource_id uuid NOT NULL,version integer NOT NULL CHECK(version>=1),payload jsonb NOT NULL,payload_sha256 text NOT NULL CHECK(payload_sha256 ~ '^[a-f0-9]{64}$'),published_by uuid NOT NULL REFERENCES public.users(id),published_at timestamptz NOT NULL DEFAULT clock_timestamp(),replaced_by uuid,FOREIGN KEY(tenant_id,school_id) REFERENCES public.schools(tenant_id,id),UNIQUE(tenant_id,school_id,resource_type,resource_id,version),UNIQUE(tenant_id,school_id,id));
CREATE INDEX academic_snapshot_lookup_idx ON public.academic_publication_snapshots(tenant_id,school_id,resource_type,resource_id,version DESC);
CREATE OR REPLACE FUNCTION app.g03e_block_snapshot_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,app AS $$BEGIN RAISE EXCEPTION 'Published snapshots are append-only'; END$$;
CREATE TRIGGER academic_snapshot_append_only BEFORE UPDATE OR DELETE ON public.academic_publication_snapshots FOR EACH ROW EXECUTE FUNCTION app.g03e_block_snapshot_mutation();
CREATE TRIGGER academic_events_append_only BEFORE UPDATE OR DELETE ON public.academic_workflow_events FOR EACH ROW EXECUTE FUNCTION app.g03e_block_snapshot_mutation();
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['academic_workflow_events','academic_revision_requests','academic_publication_snapshots'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t);END LOOP;END$$;
REVOKE ALL ON public.academic_workflow_events,public.academic_revision_requests,public.academic_publication_snapshots FROM PUBLIC;
REVOKE ALL ON FUNCTION app.g03e_block_snapshot_mutation() FROM PUBLIC;
COMMIT;
